    71	async function fetchTicketmasterEvents(city = 'Stockholm', countryCode = 'SE', size = 50) {
    72	  const url = `https://app.ticketmaster.com/discovery/v2/events.json?apikey=${TICKETMASTER_API_KEY}&city=${city}&countryCode=${countryCode}&size=${size}&sort=date,asc`;
