    74	  console.log(`[api] Fetching Ticketmaster events for ${city}...`);
    75	  
    76	  try {
    77	    const response = await axios.get(url, { timeout: 15000 });
    78	    
    79	    if (response.status !== 200) {
    80	      console.log(`[api] Ticketmaster returned ${response.status}`);
    81	      return { error: `HTTP ${response.status}`, events: [] };
    82	    }
    83	    
    84	    const data = response.data;
    85	    
    86	    if (!data._embedded || !data._embedded.events) {
    87	      console.log(`[api] No events found`);
    88	      return { events: [], count: 0 };
    89	    }
    90	    
    91	    const events = data._embedded.events.map(ev => ({
    92	      id: ev.id,
    93	      title: ev.name,
    94	      date: ev.dates?.start?.localDate || '',
    95	      time: ev.dates?.start?.localTime ? ev.dates.start.localTime.substring(0, 5) : '',
    96	      venue: ev._embedded?.venues?.[0]?.name || 'Unknown',
    97	      area: ev._embedded?.venues?.[0]?.city?.name || city,
    98	      description: ev.info || ev.pleaseNote || '',
    99	      url: ev.url || '',
   100	      source: 'ticketmaster',
   101	      imageUrl: ev.images?.[0]?.url || null,
   102	      priceRanges: ev.priceRanges || [],
   103	    }));
   104	    
   105	    console.log(`[api] Ticketmaster: ${events.length} events`);
   106	    return { events, count: events.length };
   107	  } catch (error) {
   108	    console.error(`[api] Ticketmaster error: ${error.message}`);
   109	    return { error: error.message, events: [] };
   110	  }
   111	}
